def panel_compare(result, *, min_panels: int = 2) -> dict:
    """Compare each scale of a :func:`profile_panel_set` result to the first.

    ``result`` must be a complete :func:`profile_panel_set` result
    (schema ``climate-grid/psd-panel-v1``), validated against that
    contract.  ``min_panels`` must be a non-bool positive ``int``.  A
    wrong container or entry type raises ``TypeError``; any other
    contract violation, or a non-finite or overflowing derived value,
    raises ``ValueError``.

    The first scale is the reference.  For each of the remaining
    scales and each minimum the two rows are paired and ``count`` is
    the smaller of the two rows' counts.  When ``count`` is smaller
    than ``min_panels`` the row's ``d`` and ``u`` are ``None`` lists
    as long as ``thresholds``, ``band`` is an equal-length list of
    ``[None, None]`` lists and ``pd``, ``pu`` and ``pband`` are
    ``None``, ``None`` and ``[None, None]``.  Otherwise, for each
    threshold, ``d`` is the scale's ``d`` minus the reference ``d``,
    ``u`` is ``hypot(scale u, reference u)`` and ``band`` is the
    two-item list ``[d - factor * u, d + factor * u]``; the rows'
    peaks use the same formulas, giving ``pd``, ``pu`` and ``pband``.

    The returned mapping uses the key order ``schema, factor,
    reference, scales, panels, minimums, thresholds, data``;
    ``schema`` is ``climate-grid/pc-v1``, ``factor`` is taken from
    the result, ``reference`` is the first scale, ``scales`` lists
    the remaining scales in result order and the other axes are
    fresh copies in their original order.  ``data`` follows scale
    order then minimum order; each row uses the key order ``scale,
    minimum, count, d, u, band, pd, pu, pband`` where ``d``, ``u``
    and ``band`` follow threshold order and each ``band`` entry and
    ``pband`` are two-item lists.  Every derived float is
    ``round(x, 12)`` with negative zero normalized to ``0.0``; every
    output list is newly constructed and the input is not modified.
    """
    factor, result_scales, panels, minimums, thresholds, rows = (
        _validate_profile_panel_set_result(result, where="result")
    )

    if not isinstance(min_panels, int) or isinstance(min_panels, bool):
        raise TypeError("min_panels must be a non-bool int")
    if min_panels < 1:
        raise ValueError("min_panels must be positive")

    reference = result_scales[0]
    scales = result_scales[1:]
    n_minimums = len(minimums)
    n_thresholds = len(thresholds)
    reference_rows = rows[:n_minimums]

    data: list[dict] = []
    for scale_index, scale in enumerate(scales):
        scale_rows = rows[
            (scale_index + 1) * n_minimums:(scale_index + 2) * n_minimums
        ]
        for minimum_index, minimum in enumerate(minimums):
            reference_row = reference_rows[minimum_index]
            row = scale_rows[minimum_index]
            count = min(row["count"], reference_row["count"])

            if count < min_panels:
                data.append(
                    {
                        "scale": scale,
                        "minimum": minimum,
                        "count": count,
                        "d": [None for _threshold in thresholds],
                        "u": [None for _threshold in thresholds],
                        "band": [
                            [None, None] for _threshold in thresholds
                        ],
                        "pd": None,
                        "pu": None,
                        "pband": [None, None],
                    }
                )
                continue

            d_values: list[float] = []
            u_values: list[float] = []
            band_values: list[list[float]] = []
            for threshold_index in range(n_thresholds):
                d = _as_finite_float(row["d"][threshold_index]) - (
                    _as_finite_float(reference_row["d"][threshold_index])
                )
                u = math.hypot(
                    _as_finite_float(row["u"][threshold_index]),
                    _as_finite_float(reference_row["u"][threshold_index]),
                )
                try:
                    lower = d - factor * u
                    upper = d + factor * u
                except OverflowError:
                    # Huge int factors overflow float arithmetic.
                    raise ValueError(
                        "derived statistics must be finite"
                    ) from None
                if not all(
                    _is_finite(value) for value in (d, u, lower, upper)
                ):
                    raise ValueError("derived statistics must be finite")
                d_values.append(_round_output(d))
                u_values.append(_round_output(u))
                band_values.append(
                    [_round_output(lower), _round_output(upper)]
                )

            pd = _as_finite_float(row["pd"]) - _as_finite_float(
                reference_row["pd"]
            )
            pu = math.hypot(
                _as_finite_float(row["pu"]),
                _as_finite_float(reference_row["pu"]),
            )
            try:
                peak_lower = pd - factor * pu
                peak_upper = pd + factor * pu
            except OverflowError:
                # Huge int factors overflow float arithmetic.
                raise ValueError("derived statistics must be finite") from None
            if not all(
                _is_finite(value) for value in (pd, pu, peak_lower, peak_upper)
            ):
                raise ValueError("derived statistics must be finite")

            data.append(
                {
                    "scale": scale,
                    "minimum": minimum,
                    "count": count,
                    "d": d_values,
                    "u": u_values,
                    "band": band_values,
                    "pd": _round_output(pd),
                    "pu": _round_output(pu),
                    "pband": [
                        _round_output(peak_lower),
                        _round_output(peak_upper),
                    ],
                }
            )

    return {
        "schema": _PANEL_COMPARE_SCHEMA,
        "factor": _round_output(factor),
        "reference": reference,
        "scales": list(scales),
        "panels": list(panels),
        "minimums": list(minimums),
        "thresholds": list(thresholds),
        "data": data,
    }


