def _validate_panel_sum_result(result: Any, *, where: str) -> tuple:
    """Validate a complete :func:`panel_sum` result.

    Returns the ``factor``, the ``scenarios`` and ``reference`` axes,
    the ``scales``, ``panels``, ``minimums`` and ``thresholds`` axes
    and the ``data`` rows, checking the ``climate-grid/pcs-v1``
    contract: key order, the schema, a finite positive factor rounded
    to 12 digits, the axes, one data row per ``(scale, minimum)`` pair
    in scale then minimum order and each row's key order ``scale,
    minimum, count, d, u, band, pd, pu, pband``.  ``count`` is a
    non-negative int; ``d``, ``u`` and ``band`` hold one entry per
    threshold and each ``band`` entry and ``pband`` are two-item lists.
    Every statistic entry is either ``None`` or a finite value rounded
    to 12 digits; non-``None`` ``u`` and ``pu`` values are
    non-negative.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _PANEL_SUM_OUTPUT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, factor, "
            "scenarios, reference, scales, panels, minimums, thresholds, "
            "data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _PANEL_SUM_SCHEMA:
        raise ValueError(f"{where}.schema must be {_PANEL_SUM_SCHEMA!r}")

    factor = result["factor"]
    if not isinstance(factor, (int, float)) or isinstance(factor, bool):
        raise TypeError(
            f"{where}.factor must be a finite non-bool int or float"
