def panel_region_delta(items, *, minimum: int = 1) -> dict:
    """Compare :func:`panel_sum` results of other regions to the first.

    ``items`` must be a list of at least two dicts whose keys are
    exactly ``region, result`` in that order; ``region`` is a unique
    non-empty ``str`` and ``result`` a complete :func:`panel_sum`
    result (schema ``climate-grid/pcs-v1``), validated against that
    contract.  Every result must hold the same ``factor``,
    ``scenarios``, ``reference``, ``scales``, ``panels``,
    ``minimums`` and ``thresholds``; only the ``data`` rows may
    differ.  ``minimum`` must be a non-bool positive ``int``.  A wrong
    container or entry type raises ``TypeError``; any other contract
    violation, or a non-finite or overflowing derived value, raises
    ``ValueError``.

    The first item is the baseline region.  Each remaining item is
    paired to it by ``region``, then ``scale``, then ``minimum``; for
    every pair ``count`` is the smaller of the two rows' counts.
    When ``count`` is smaller than ``minimum``, or either row's
    threshold-wise ``d`` or ``u`` holds a ``None``, the row's
    ``delta`` and ``u`` are ``None`` lists as long as ``thresholds``
    and ``interval`` is an equal-length list of ``[None, None]``
    lists.  Otherwise, for each threshold, ``delta`` is the current
    region's ``d`` minus the baseline region's ``d``, ``u`` is
    ``hypot(current u, baseline u)`` and ``interval`` is the two-item
    list ``[delta - factor * u, delta + factor * u]``.

    The returned mapping uses the key order ``schema, reference,
    thresholds, data``; ``schema`` is ``climate-grid/prd-v1``,
    ``reference`` is the first item's region and ``thresholds`` is a
    fresh copy of the results' thresholds in their original order.
    ``data`` follows remaining-item (region) order then scale order
    then minimum order; each row uses the key order ``region, scale,
    minimum, count, delta, u, interval`` where ``delta``, ``u`` and
    ``interval`` follow threshold order and each ``interval`` entry
    is a two-item list.  Every derived float is ``round(x, 12)`` with
    negative zero normalized to ``0.0``; every output list is newly
    constructed and the input is not modified.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least two items")

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    regions: list[str] = []
    results: list[tuple] = []
    seen: set[str] = set()
    for item_index, item in enumerate(items):
        item_where = f"items[{item_index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be a dict")
        if tuple(item.keys()) != _PANEL_REGION_DELTA_ITEM_KEYS:
            raise ValueError(
                f"{item_where} must have exactly the keys region, result "
                "in order"
            )

        region = item["region"]
        if not isinstance(region, str):
            raise TypeError(f"{item_where}.region must be a str")
        if region == "":
            raise ValueError(f"{item_where}.region must be non-empty")
        if region in seen:
            raise ValueError(f"duplicate items region: {region!r}")
        seen.add(region)
        regions.append(region)
        results.append(
            _validate_panel_sum_result(
                item["result"], where=f"{item_where}.result"
            )
        )

    factor, scenarios, reference, scales, panels, minimums, thresholds, _ = (
        results[0]
    )
    for item_index, other in enumerate(results[1:], start=1):
        if other[:7] != (
            factor,
            scenarios,
            reference,
            scales,
            panels,
            minimums,
            thresholds,
        ):
            raise ValueError(
                f"items[{item_index}].result must have the same factor, "
                "scenarios, reference, scales, panels, minimums and "
                "thresholds as every other result"
            )

    n_minimums = len(minimums)
    n_thresholds = len(thresholds)
    baseline_rows = results[0][7]

    data: list[dict] = []
    for item_index in range(1, len(results)):
        region = regions[item_index]
        rows = results[item_index][7]
        for scale_index, scale in enumerate(scales):
            for minimum_index, minimum_value in enumerate(minimums):
                row_index = scale_index * n_minimums + minimum_index
                current_row = rows[row_index]
                baseline_row = baseline_rows[row_index]
                count = min(current_row["count"], baseline_row["count"])

                if (
                    count < minimum
                    or any(value is None for value in current_row["d"])
                    or any(value is None for value in current_row["u"])
                    or any(value is None for value in baseline_row["d"])
                    or any(value is None for value in baseline_row["u"])
                ):
                    data.append(
                        {
                            "region": region,
                            "scale": scale,
                            "minimum": minimum_value,
                            "count": count,
                            "delta": [None for _threshold in thresholds],
                            "u": [None for _threshold in thresholds],
                            "interval": [
                                [None, None] for _threshold in thresholds
                            ],
                        }
                    )
                    continue

                delta_values: list = []
                u_values: list = []
                interval_values: list[list] = []
                for threshold_index in range(n_thresholds):
                    delta = _as_finite_float(
                        current_row["d"][threshold_index]
                    ) - _as_finite_float(
                        baseline_row["d"][threshold_index]
                    )
                    u = math.hypot(
                        _as_finite_float(current_row["u"][threshold_index]),
                        _as_finite_float(baseline_row["u"][threshold_index]),
                    )
                    try:
                        lower = delta - factor * u
                        upper = delta + factor * u
                    except OverflowError:
                        # Huge int factors overflow float arithmetic.
                        raise ValueError(
                            "derived statistics must be finite"
                        ) from None
                    if not all(
                        _is_finite(value) for value in (delta, u, lower, upper)
                    ):
                        raise ValueError("derived statistics must be finite")
                    delta_values.append(_round_output(delta))
                    u_values.append(_round_output(u))
                    interval_values.append(
                        [_round_output(lower), _round_output(upper)]
                    )

                data.append(
                    {
                        "region": region,
                        "scale": scale,
                        "minimum": minimum_value,
                        "count": count,
                        "delta": delta_values,
                        "u": u_values,
                        "interval": interval_values,
                    }
                )

    return {
        "schema": _PANEL_REGION_DELTA_SCHEMA,
        "reference": regions[0],
        "thresholds": list(thresholds),
        "data": data,
    }

