        raise ValueError("items must contain at least two items")

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    regions: list[str] = []
    results: list[tuple] = []
    seen: set[str] = set()
    for item_index, item in enumerate(items):
        item_where = f"items[{item_index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be a dict")
        if tuple(item.keys()) != _PANEL_REGION_DELTA_ITEM_KEYS:
            raise ValueError(
                f"{item_where} must have exactly the keys region, result "
                "in order"
            )

        region = item["region"]
        if not isinstance(region, str):
            raise TypeError(f"{item_where}.region must be a str")
        if region == "":
            raise ValueError(f"{item_where}.region must be non-empty")
        if region in seen:
            raise ValueError(f"duplicate items region: {region!r}")
        seen.add(region)
        regions.append(region)
        results.append(
            _validate_panel_sum_result(
                item["result"], where=f"{item_where}.result"
            )
        )

    factor, scenarios, reference, scales, panels, minimums, thresholds, _ = (
        results[0]
    )
    for item_index, other in enumerate(results[1:], start=1):
        if other[:7] != (
            factor,
            scenarios,
            reference,
            scales,
            panels,
            minimums,
            thresholds,
        ):
            raise ValueError(
                f"items[{item_index}].result must have the same factor, "
                "scenarios, reference, scales, panels, minimums and "
                "thresholds as every other result"
            )

    n_minimums = len(minimums)
    n_thresholds = len(thresholds)
    baseline_rows = results[0][7]

    data: list[dict] = []
    for item_index in range(1, len(results)):
        region = regions[item_index]
        rows = results[item_index][7]
        for scale_index, scale in enumerate(scales):
            for minimum_index, minimum_value in enumerate(minimums):
                row_index = scale_index * n_minimums + minimum_index
                current_row = rows[row_index]
                baseline_row = baseline_rows[row_index]
                count = min(current_row["count"], baseline_row["count"])

                if (
                    count < minimum
                    or any(value is None for value in current_row["d"])
                    or any(value is None for value in current_row["u"])
                    or any(value is None for value in baseline_row["d"])
                    or any(value is None for value in baseline_row["u"])
                ):
                    data.append(
                        {
                            "region": region,
                            "scale": scale,
                            "minimum": minimum_value,
                            "count": count,
                            "delta": [None for _threshold in thresholds],
                            "u": [None for _threshold in thresholds],
                            "interval": [
                                [None, None] for _threshold in thresholds
                            ],
                        }
                    )
                    continue

                delta_values: list = []
                u_values: list = []
                interval_values: list[list] = []
                for threshold_index in range(n_thresholds):
                    delta = _as_finite_float(
                        current_row["d"][threshold_index]
                    ) - _as_finite_float(
                        baseline_row["d"][threshold_index]
                    )
                    u = math.hypot(
                        _as_finite_float(current_row["u"][threshold_index]),
                        _as_finite_float(baseline_row["u"][threshold_index]),
                    )
                    try:
                        lower = delta - factor * u
                        upper = delta + factor * u
                    except OverflowError:
                        # Huge int factors overflow float arithmetic.
                        raise ValueError(
                            "derived statistics must be finite"
                        ) from None
                    if not all(
                        _is_finite(value) for value in (delta, u, lower, upper)
                    ):
                        raise ValueError("derived statistics must be finite")
                    delta_values.append(_round_output(delta))
                    u_values.append(_round_output(u))
                    interval_values.append(
                        [_round_output(lower), _round_output(upper)]
                    )

                data.append(
                    {
                        "region": region,
                        "scale": scale,
                        "minimum": minimum_value,
                        "count": count,
                        "delta": delta_values,
                        "u": u_values,
                        "interval": interval_values,
                    }
                )

    return {
        "schema": _PANEL_REGION_DELTA_SCHEMA,
        "reference": regions[0],
        "thresholds": list(thresholds),
        "data": data,
    }
